#!/bin/bash
for url in $(curl -s -m 10 https://status.astralis-cloud.example | grep -Eo 'https://api.astralis-cloud.example/v1/[a-zA-Z0-9./_-]+' | sort -u); do path=$(echo "$url" | sed 's|https://api.astralis-cloud.example||'); if ! curl -s -m 10 https://api.astralis-cloud.example/v1/docs/openapi.json | jq -r '(.paths, .components) | objects | keys[]' | grep -qx "$path"; then code=$(curl -s -o /dev/null -w "%{http_code}" -m 5 "$url"); if [ "$code" = "200" ] || [ "$code" = "301" ] || [ "$code" = "302" ] || [ "$code" = "401" ] || [ "$code" = "403" ]; then echo "https://api.astralis-cloud.example$path"; exit 0; fi; fi; done
